window.receiveProjectSource({"path": "test/integration/web_extraction/test_syndication_classification.py", "lines": ["import asyncio", "import json", "from datetime import datetime, timezone", "from math import sqrt", "from uuid import UUID, uuid4", "", "import numpy as np", "import pytest", "from sqlalchemy import select, text", "", "import common.models.all as Tables", "from common.exceptions.exceptions import DatabaseWriteException", "from common.services.api_helper import APIHelper", "from db.session_manager_async import sessionmanager_datalake", "from microservices.web_extraction.config import config as web_config", "from microservices.web_extraction.models import (", "    SourceClassification,", "    SourceClassificationGroup,", "    WebExtractionResponse,", ")", "from microservices.web_extraction.schemas import ArticleSchema", "from microservices.web_extraction.schemas.article_base_schemas import (", "    ArticleItem,", "    RawAPIResponse,", ")", "from microservices.web_extraction.schemas.embedding import ChunkEmbedding, ChunkVectors", "from microservices.web_extraction.services.helpers import borderline_verifier", "from microservices.web_extraction.services.helpers.layer_two import (", "    DeduplicationClassification,", "    deduplicate_article,", ")", "from microservices.web_extraction.services.helpers.layer_two_classification import (", "    LayerTwoRetryContext,", "    classify_layer_two_article,", ")", "from microservices.web_extraction.services.helpers.source_classification import (", "    CLASSIFICATION_METHOD_VECTOR,", "    _resolve_or_materialize_group_for_article,", "    attach_article_to_group,", ")", "from test.integration._shared.db import get_test_feeds", "from test.integration._shared.preseeding import (", "    preseed_feeds_sent_messages,", "    preseed_responses,", "    preseed_webex_l1_activities,", "    preseed_webex_l2_activities,", "    preseed_webex_sent_messages,", ")", "", "pytestmark = pytest.mark.integration", "", "", "def _embedding(first: float, second: float) -> list[float]:", "    vec = [0.0] * 3072", "    vec[0] = first", "    vec[1] = second", "    return vec", "", "", "def _chunk_vectors(first: float, second: float) -> ChunkVectors:", "    return ChunkVectors(", "        chunks=[", "            ChunkEmbedding(", "                chunk_index=0,", "                chunk_text=\"candidate chunk\",", "                token_count=8,", "                embedding=_embedding(first, second),", "            )", "        ]", "    )", "", "", "async def _seed_response_ids(count: int) -> list[UUID]:", "    async with sessionmanager_datalake.session() as session:", "        feeds = await get_test_feeds(db=session, num_feeds=1)", "        feeds_sent_msgs, _ = await preseed_feeds_sent_messages(db=session, feeds=feeds)", "        _, l1_activity_ids = await preseed_webex_l1_activities(", "            db=session,", "            feeds=feeds,", "            feeds_sent_msgs=feeds_sent_msgs,", "        )", "        _, l2_source_msg_ids = await preseed_webex_sent_messages(", "            db=session,", "            layer_one_activity_id=l1_activity_ids[0],", "            num_layer_one_child_messages=count,", "        )", "        _, l2_activity_ids = await preseed_webex_l2_activities(", "            db=session,", "            webex_l1_activity_id=l1_activity_ids[0],", "            sqs_msg_ids=l2_source_msg_ids,", "            num_activities=count,", "        )", "        _, response_ids = await preseed_responses(", "            db=session,", "            layer_two_activity_ids=l2_activity_ids,", "        )", "    return response_ids", "", "", "@pytest.mark.asyncio", "async def test_deduplicate_article_picks_nearest_match(clean_article_tables):", "    \"\"\"L2-style classification through ``deduplicate_article``: with two", "    candidate articles of varying similarity, the nearest one wins and the", "    article-aggregate score lands in the expected band.", "    \"\"\"", "    async with sessionmanager_datalake.session() as session:", "        syndicated_article = Tables.Article()", "        duplicate_article = Tables.Article()", "        session.add_all([syndicated_article, duplicate_article])", "        await session.flush()", "        session.add_all(", "            [", "                Tables.ArticleChunk(", "                    article_id=syndicated_article.id,", "                    chunk_index=0,", "                    chunk_text=\"syndicated-candidate\",", "                    embedding=_embedding(0.85, sqrt(1 - (0.85**2))),", "                ),", "                Tables.ArticleChunk(", "                    article_id=duplicate_article.id,", "                    chunk_index=0,", "                    chunk_text=\"duplicate-candidate\",", "                    embedding=_embedding(1.0, 0.0),", "                ),", "            ]", "        )", "        await session.commit()", "", "        result = await deduplicate_article(session, _chunk_vectors(1.0, 0.0))", "", "    assert result.classification == DeduplicationClassification.DUPLICATE", "    assert result.best_match is not None", "    assert result.best_match.article_id == duplicate_article.id", "    assert result.article_score >= 0.99", "", "", "def _unit_vec(seed: int, dim: int = 3072) -> np.ndarray:", "    rng = np.random.RandomState(seed)", "    v = rng.randn(dim)", "    return v / np.linalg.norm(v)", "", "", "def _perturb_to_similarity(base: np.ndarray, target_sim: float, seed: int) -> np.ndarray:", "    rng = np.random.RandomState(seed)", "    orth = rng.randn(len(base))", "    orth -= np.dot(orth, base) * base", "    orth /= np.linalg.norm(orth)", "    return target_sim * base + sqrt(1 - target_sim**2) * orth", "", "", "@pytest.mark.asyncio", "async def test_dedup_recall_with_per_chunk_competitors(clean_article_tables):", "    \"\"\"Locks in DEDUP_TOP_K width: when each incoming chunk has multiple", "    competitor articles whose chunks rank above the duplicate's chunk on that", "    incoming index, the article-aggregate scoring must still recover the", "    duplicate via top-K visibility.", "", "    Setup: 5 incoming chunks. One true duplicate D with 5 chunks at 0.953 to", "    each corresponding incoming chunk. For each incoming chunk i, four", "    competitor articles each contribute one chunk at 0.97 / 0.965 / 0.96 /", "    0.955 (all just above D's 0.953 on incoming chunk i, but each competitor", "    only matches one incoming chunk).", "", "    Per-chunk ranks for incoming chunk i: [comp_i_a, comp_i_b, comp_i_c,", "    comp_i_d, D_chunk_i, ...]. With K<5, D's chunks fall outside top-K and", "    coverage drops to 0 \u2014 D classifies UNIQUE despite being the obvious", "    article-level duplicate. With K>=5 (default 15), D's chunks surface and", "    coverage is 5/5 \u2192 DUPLICATE.", "", "    Note on similarities: D sits at 0.953 rather than the threshold edge", "    of 0.95 because the realized cosine between an embedding stored in", "    pgvector and the Python-side incoming vector loses a few decimal", "    places of precision (vector storage + halfvec ANN cast). Anchoring D", "    a few thousandths above the threshold keeps the score reliably", "    > ``DEDUP_DUPLICATE_THRESHOLD`` (0.95) without changing the", "    competitor-outranks-D invariant.", "", "    Regression guard: catches PRs that lower DEDUP_TOP_K below the", "    competitor-pool depth this scenario assumes.", "    \"\"\"", "    incoming_vecs = [_unit_vec(seed=i) for i in range(5)]", "    competitor_similarities = [0.97, 0.965, 0.96, 0.955]", "", "    async with sessionmanager_datalake.session() as session:", "        duplicate_article = Tables.Article()", "        session.add(duplicate_article)", "        await session.flush()", "        session.add_all(", "            [", "                Tables.ArticleChunk(", "                    article_id=duplicate_article.id,", "                    chunk_index=i,", "                    chunk_text=f\"dup-{i}\",", "                    embedding=_perturb_to_similarity(", "                        incoming_vecs[i], 0.953, seed=100 + i", "                    ).tolist(),", "                )", "                for i in range(5)", "            ]", "        )", "", "        # 4 competitors per incoming chunk = 20 competitor articles total.", "        competitor_articles = [Tables.Article() for _ in range(5 * len(competitor_similarities))]", "        session.add_all(competitor_articles)", "        await session.flush()", "        chunks_to_add = []", "        for i in range(5):", "            for j, sim in enumerate(competitor_similarities):", "                comp_idx = i * len(competitor_similarities) + j", "                chunks_to_add.append(", "                    Tables.ArticleChunk(", "                        article_id=competitor_articles[comp_idx].id,", "                        chunk_index=0,", "                        chunk_text=f\"comp-{i}-{j}\",", "                        embedding=_perturb_to_similarity(", "                            incoming_vecs[i], sim, seed=200 + comp_idx", "                        ).tolist(),", "                    )", "                )", "        session.add_all(chunks_to_add)", "        await session.commit()", "", "        incoming = ChunkVectors(", "            chunks=[", "                ChunkEmbedding(", "                    chunk_index=i,", "                    chunk_text=f\"incoming-{i}\",", "                    token_count=8,", "                    embedding=incoming_vecs[i].tolist(),", "                )", "                for i in range(5)", "            ]", "        )", "        result = await deduplicate_article(session, incoming)", "", "    assert result.classification == DeduplicationClassification.DUPLICATE, (", "        f\"Expected DUPLICATE despite {len(competitor_similarities)} per-chunk competitors \"", "        f\"outranking the duplicate; got {result.classification.value}, \"", "        f\"score={result.article_score:.3f}. DEDUP_TOP_K may be too narrow.\"", "    )", "    assert result.best_match is not None", "    assert result.best_match.article_id == duplicate_article.id", "", "", "@pytest.mark.asyncio", "async def test_deduplicate_article_similarity_as_of_excludes_later_chunks(clean_article_tables):", "    \"\"\"``similarity_as_of`` must hide chunks with ``created_at`` after the", "    cutoff. Without it, replay classification on retry could shift when later", "    articles have been ingested between attempts.", "    \"\"\"", "    from datetime import timedelta", "", "    async with sessionmanager_datalake.session() as session:", "        before_article = Tables.Article()", "        after_article = Tables.Article()", "        session.add_all([before_article, after_article])", "        await session.flush()", "", "        before_chunk = Tables.ArticleChunk(", "            article_id=before_article.id,", "            chunk_index=0,", "            chunk_text=\"before-cutoff\",", "            embedding=_embedding(0.85, sqrt(1 - (0.85**2))),", "        )", "        session.add(before_chunk)", "        await session.commit()", "        await session.refresh(before_chunk)", "", "        # Force at least 2ms between the two inserts so the server-side", "        # ``created_at`` defaults differ by more than the test's cutoff", "        # epsilon. Without this gap, single-microsecond CLOCK_REALTIME", "        # ticks on a fast machine can produce equal or out-of-order", "        # timestamps (Postgres ``now()`` returns transaction start time;", "        # back-to-back transactions can collide at microsecond resolution).", "        await asyncio.sleep(0.002)", "", "        after_chunk = Tables.ArticleChunk(", "            article_id=after_article.id,", "            chunk_index=0,", "            chunk_text=\"after-cutoff\",", "            embedding=_embedding(1.0, 0.0),  # closer to incoming", "        )", "        session.add(after_chunk)", "        await session.commit()", "        await session.refresh(after_chunk)", "", "        # Cutoff between the two created_at timestamps. before_chunk passes,", "        # after_chunk does not. Server times can drift relative to the test", "        # process, so anchor the cutoff on the actual stored values.", "        cutoff = before_chunk.created_at + timedelta(microseconds=1)", "        assert cutoff < after_chunk.created_at, (", "            \"Test setup invariant: after_chunk must be created after before_chunk\"", "        )", "", "        result = await deduplicate_article(", "            session,", "            _chunk_vectors(1.0, 0.0),", "            similarity_as_of=cutoff,", "        )", "", "    # Without similarity_as_of, after_article (similarity ~1.0) would win.", "    # With the cutoff, only before_article is visible.", "    assert result.best_match is not None", "    assert result.best_match.article_id == before_article.id", "    assert result.classification != DeduplicationClassification.UNIQUE", "", "", "@pytest.mark.asyncio", "async def test_dedup_retry_query_uses_hnsw_index(clean_article_tables):", "    \"\"\"The retry-path dedup query (``WHERE article_id != ...`` + halfvec ANN", "    ORDER BY) must use the HNSW expression index ``ix_article_chunks_embedding_cosine``,", "    not fall through to a sequential scan over ``article_chunks``.", "", "    Regression guard: the previous retry path used a SQLAlchemy ``Select``", "    with ``ArticleChunk.embedding.cosine_distance(...)`` against the raw", "    ``vector(3072)`` column, bypassing the halfvec(3072) expression index.", "    At ~1M chunks that degrades to multi-second seq scans per incoming", "    chunk per retry. We force ``enable_seqscan = off`` so the assertion", "    measures *applicability* of the index, not whether the cost model", "    happens to prefer it at the test row count.", "    \"\"\"", "    async with sessionmanager_datalake.session() as session:", "        articles = [Tables.Article() for _ in range(2)]", "        session.add_all(articles)", "        await session.flush()", "        session.add_all(", "            [", "                Tables.ArticleChunk(", "                    article_id=articles[i % 2].id,", "                    chunk_index=i,", "                    chunk_text=f\"chunk {i}\",", "                    embedding=_embedding(float((i % 5) / 5), float(((i + 1) % 5) / 5)),", "                )", "                for i in range(20)", "            ]", "        )", "        await session.commit()", "", "    excluded = articles[0].id", "    qvec = \"[\" + \",\".join([\"0.0\"] * 3072) + \"]\"", "", "    async with sessionmanager_datalake.session() as session:", "        await session.execute(text(\"SET LOCAL enable_seqscan = off\"))", "        await session.execute(text(\"SET LOCAL hnsw.iterative_scan = 'relaxed_order'\"))", "        result = await session.execute(", "            text(", "                \"EXPLAIN (FORMAT JSON) \"", "                \"SELECT id FROM web_extraction.article_chunks \"", "                \"WHERE article_id != CAST(:exclude_article_id AS uuid) \"", "                \"ORDER BY (embedding::halfvec(3072)) <=> (:qvec)::halfvec(3072) \"", "                \"LIMIT 5\"", "            ).bindparams(exclude_article_id=str(excluded), qvec=qvec)", "        )", "        plan = result.scalar_one()", "", "    plan_str = json.dumps(plan)", "    assert \"ix_article_chunks_embedding_cosine\" in plan_str, (", "        f\"retry-path query did not use HNSW expression index; plan: {plan_str}\"", "    )", "", "", "@pytest.mark.asyncio", "async def test_dedup_retry_finds_match_in_other_article_when_excluded_dominates_topk(", "    clean_article_tables,", "):", "    \"\"\"End-to-end behavioural test for the iterative_scan retry path.", "", "    Setup: the excluded article holds K+1 chunks all very close to the incoming", "    embedding. A second, non-excluded article holds a single chunk that is", "    also a strong match but slightly farther. With a vanilla HNSW", "    ``WHERE article_id != ...`` post-filter, the excluded article's chunks", "    fill top-K and the second article's chunk gets dropped \u2014 the retry", "    classifies the article as UNIQUE even though the true nearest", "    non-excluded match is a duplicate.", "", "    With ``hnsw.iterative_scan = relaxed_order`` set on the dedup", "    transaction, the HNSW walker keeps going past LIMIT until K rows pass", "    the WHERE filter, recovering the second article's match. This test", "    asserts we see a non-UNIQUE classification on that scenario.", "", "    The chunk count is derived from ``DEDUP_TOP_K`` so the test stays", "    correct as K is tuned \u2014 a hardcoded count would silently stop", "    exercising the iterative-scan path when K is bumped above it.", "    \"\"\"", "    target_first, target_second = 1.0, 0.0", "    excluded_chunk_count = web_config.DEDUP_TOP_K + 1", "", "    async with sessionmanager_datalake.session() as session:", "        excluded_article = Tables.Article()", "        other_article = Tables.Article()", "        session.add_all([excluded_article, other_article])", "        await session.flush()", "", "        # Excluded article: many chunks at ~1.0 similarity to (1, 0).", "        session.add_all(", "            [", "                Tables.ArticleChunk(", "                    article_id=excluded_article.id,", "                    chunk_index=i,", "                    chunk_text=f\"excluded {i}\",", "                    embedding=_embedding(target_first, target_second),", "                )", "                for i in range(excluded_chunk_count)", "            ]", "        )", "        # Non-excluded article: one chunk slightly farther but still well above", "        # the duplicate threshold.", "        session.add(", "            Tables.ArticleChunk(", "                article_id=other_article.id,", "                chunk_index=0,", "                chunk_text=\"other 0\",", "                embedding=_embedding(0.97, sqrt(1 - 0.97**2)),", "            )", "        )", "        await session.commit()", "", "        incoming = ChunkVectors(", "            chunks=[", "                ChunkEmbedding(", "                    chunk_index=0,", "                    chunk_text=\"incoming\",", "                    token_count=8,", "                    embedding=_embedding(target_first, target_second),", "                )", "            ]", "        )", "", "        result = await deduplicate_article(", "            session,", "            incoming,", "            exclude_article_id=excluded_article.id,", "        )", "", "    # The non-excluded article must surface as the match \u2014 not UNIQUE.", "    assert result.classification != DeduplicationClassification.UNIQUE, (", "        f\"retry classified UNIQUE despite a strong non-excluded match; score={result.article_score}\"", "    )", "    assert result.best_match is None or result.best_match.article_id == other_article.id", "", "", "@pytest.mark.asyncio", "async def test_syndication_group_assignment_and_primary_reevaluation(clean_article_tables):", "    response_ids = await _seed_response_ids(2)", "    async with sessionmanager_datalake.session() as session:", "        matched_article = Tables.Article()", "        new_article = Tables.Article()", "        session.add_all([matched_article, new_article])", "        await session.flush()", "", "        session.add_all(", "            [", "                Tables.ZyteArticle(", "                    article_id=matched_article.id,", "                    response_id=response_ids[0],", "                    article_url=\"https://example.com/matched\",", "                    article_title=\"matched\",", "                    content=\"matched\",", "                    date_published=datetime(2026, 4, 5, tzinfo=timezone.utc),", "                ),", "                Tables.ZyteArticle(", "                    article_id=new_article.id,", "                    response_id=response_ids[1],", "                    article_url=\"https://example.com/new\",", "                    article_title=\"new\",", "                    content=\"new\",", "                    date_published=datetime(2026, 4, 4, tzinfo=timezone.utc),", "                ),", "            ]", "        )", "        await session.commit()", "", "        origin_activity_id = await session.scalar(", "            select(WebExtractionResponse.layer_two_activity_id).where(", "                WebExtractionResponse.id == response_ids[1]", "            )", "        )", "        assert origin_activity_id is not None", "", "        # Pre-resolve the matched article's group, as the production flow does", "        # via resolve_retry_syndication_group_id \u2192 _resolve_or_materialize_group_for_article.", "        matched_singleton = await attach_article_to_group(", "            session,", "            article_id=matched_article.id,", "            matched_article_id=None,", "            similarity_score=None,", "            classification_method=CLASSIFICATION_METHOD_VECTOR,", "            origin_activity_id=origin_activity_id,", "        )", "        group_id = matched_singleton.syndication_group_id", "", "        classification_row = await attach_article_to_group(", "            session,", "            article_id=new_article.id,", "            matched_article_id=matched_article.id,", "            similarity_score=0.86,", "            classification_method=CLASSIFICATION_METHOD_VECTOR,", "            frozen_group_id=group_id,", "        )", "        assert classification_row.syndication_group_id == group_id", "", "        rows = (", "            (", "                await session.execute(", "                    select(SourceClassification).where(", "                        SourceClassification.article_id.in_([matched_article.id, new_article.id])", "                    )", "                )", "            )", "            .scalars()", "            .all()", "        )", "        assert len(rows) == 2", "        assert {row.syndication_group_id for row in rows} == {group_id}", "        group = await session.get(SourceClassificationGroup, group_id)", "        assert group is not None", "        assert group.member_count == len(rows)", "        assert group.primary_article_id == new_article.id", "        # Seed is the article whose row is inserted first \u2014 here that's the", "        # matched article (lazily created when it had no classification row).", "        assert group.seed_article_id == matched_article.id", "        assert group.origin_activity_id == origin_activity_id", "", "", "@pytest.mark.asyncio", "async def test_syndication_group_join_reuses_existing_group(clean_article_tables):", "    response_ids = await _seed_response_ids(3)", "    async with sessionmanager_datalake.session() as session:", "        primary_article = Tables.Article()", "        matched_article = Tables.Article()", "        joining_article = Tables.Article()", "        session.add_all([primary_article, matched_article, joining_article])", "        await session.flush()", "", "        group_id = uuid4()", "        session.add_all(", "            [", "                Tables.ZyteArticle(", "                    article_id=primary_article.id,", "                    response_id=response_ids[0],", "                    article_url=\"https://example.com/primary\",", "                    article_title=\"primary\",", "                    content=\"primary\",", "                    date_published=datetime(2026, 4, 3, tzinfo=timezone.utc),", "                ),", "                Tables.ZyteArticle(", "                    article_id=matched_article.id,", "                    response_id=response_ids[1],", "                    article_url=\"https://example.com/matched\",", "                    article_title=\"matched\",", "                    content=\"matched\",", "                    date_published=datetime(2026, 4, 4, tzinfo=timezone.utc),", "                ),", "                Tables.ZyteArticle(", "                    article_id=joining_article.id,", "                    response_id=response_ids[2],", "                    article_url=\"https://example.com/joining\",", "                    article_title=\"joining\",", "                    content=\"joining\",", "                    date_published=datetime(2026, 4, 6, tzinfo=timezone.utc),", "                ),", "            ]", "        )", "        await session.flush()", "", "        session.add(", "            SourceClassificationGroup(", "                id=group_id,", "                primary_article_id=primary_article.id,", "                seed_article_id=primary_article.id,", "                member_count=2,", "            )", "        )", "        await session.flush()", "", "        session.add_all(", "            [", "                SourceClassification(", "                    article_id=primary_article.id,", "                    syndication_group_id=group_id,", "                    similarity_score=None,", "                    matched_article_id=None,", "                    classification_method=\"vector\",", "                ),", "                SourceClassification(", "                    article_id=matched_article.id,", "                    syndication_group_id=group_id,", "                    similarity_score=0.83,", "                    matched_article_id=primary_article.id,", "                    classification_method=\"vector\",", "                ),", "            ]", "        )", "        await session.commit()", "", "        classification_row = await attach_article_to_group(", "            session,", "            article_id=joining_article.id,", "            matched_article_id=matched_article.id,", "            similarity_score=0.82,", "            classification_method=CLASSIFICATION_METHOD_VECTOR,", "            frozen_group_id=group_id,", "        )", "        assert classification_row.syndication_group_id == group_id", "", "        rows = (", "            (", "                await session.execute(", "                    select(SourceClassification).where(", "                        SourceClassification.syndication_group_id == group_id", "                    )", "                )", "            )", "            .scalars()", "            .all()", "        )", "        assert len(rows) == 3", "        group = await session.get(SourceClassificationGroup, group_id)", "        assert group is not None", "        assert group.member_count == len(rows)", "        assert group.primary_article_id == primary_article.id", "", "", "@pytest.mark.asyncio", "async def test_singleton_group_ids_are_non_deterministic(clean_article_tables):", "    \"\"\"Group creation must mint a random UUID, not one derived from the seed article.", "", "    Guards against any regression that reintroduces deterministic id derivation", "    (e.g. ``uuid5(article_id)``) \u2014 two singletons created for the same article", "    in fresh DB states would collide under derivation but must not collide here.", "    \"\"\"", "    response_ids = await _seed_response_ids(2)", "", "    async with sessionmanager_datalake.session() as session:", "        article_a = Tables.Article()", "        article_b = Tables.Article()", "        session.add_all([article_a, article_b])", "        await session.flush()", "        session.add_all(", "            [", "                Tables.ZyteArticle(", "                    article_id=article_a.id,", "                    response_id=response_ids[0],", "                    article_url=\"https://example.com/a\",", "                    article_title=\"a\",", "                    content=\"a\",", "                    date_published=datetime(2026, 4, 4, tzinfo=timezone.utc),", "                ),", "                Tables.ZyteArticle(", "                    article_id=article_b.id,", "                    response_id=response_ids[1],", "                    article_url=\"https://example.com/b\",", "                    article_title=\"b\",", "                    content=\"b\",", "                    date_published=datetime(2026, 4, 5, tzinfo=timezone.utc),", "                ),", "            ]", "        )", "        await session.commit()", "", "        row_a = await attach_article_to_group(", "            session,", "            article_id=article_a.id,", "            matched_article_id=None,", "            similarity_score=None,", "            classification_method=\"vector\",", "        )", "        row_b = await attach_article_to_group(", "            session,", "            article_id=article_b.id,", "            matched_article_id=None,", "            similarity_score=None,", "            classification_method=\"vector\",", "        )", "", "        assert row_a.syndication_group_id != row_b.syndication_group_id", "", "", "@pytest.mark.asyncio", "async def test_attach_skips_primary_recompute_when_new_member_cant_displace(", "    clean_article_tables, monkeypatch: pytest.MonkeyPatch", "):", "    \"\"\"When the new attachee's ``date_published`` is strictly later than the", "    current primary's, ``reevaluate_group_primary`` must NOT be called \u2014 this", "    is the hot-news-burst optimization that keeps O(N\u00b2) cumulative wallclock", "    from biting on groups of 50-200 syndicated members.", "", "    Verifies both the perf invariant (recompute not called) and the", "    correctness outcome (primary stays as the earlier-dated current primary).", "    \"\"\"", "    from microservices.web_extraction.services.helpers import source_classification as sc_mod", "", "    response_ids = await _seed_response_ids(2)", "    api_helper = APIHelper()", "    recompute_calls: list[UUID] = []", "", "    real_reevaluate = sc_mod.reevaluate_group_primary", "", "    async def _spy_reevaluate(db, syndication_group_id):", "        recompute_calls.append(syndication_group_id)", "        await real_reevaluate(db, syndication_group_id)", "", "    monkeypatch.setattr(sc_mod, \"reevaluate_group_primary\", _spy_reevaluate)", "", "    try:", "        async with sessionmanager_datalake.session() as session:", "            current_primary = Tables.Article()", "            later_attachee = Tables.Article()", "            session.add_all([current_primary, later_attachee])", "            await session.flush()", "            session.add_all(", "                [", "                    Tables.ZyteArticle(", "                        article_id=current_primary.id,", "                        response_id=response_ids[0],", "                        article_url=\"https://example.com/primary\",", "                        article_title=\"primary\",", "                        content=\"primary\",", "                        date_published=datetime(2026, 4, 4, tzinfo=timezone.utc),", "                    ),", "                    Tables.ZyteArticle(", "                        article_id=later_attachee.id,", "                        response_id=response_ids[1],", "                        article_url=\"https://example.com/later\",", "                        article_title=\"later\",", "                        content=\"later\",", "                        date_published=datetime(2026, 4, 5, tzinfo=timezone.utc),", "                    ),", "                ]", "            )", "            await session.commit()", "", "            # Seed the group via the current_primary singleton (no recompute fires", "            # for singleton creation \u2014 that's the existing short-circuit).", "            seed_row = await attach_article_to_group(", "                session,", "                article_id=current_primary.id,", "                matched_article_id=None,", "                similarity_score=None,", "                classification_method=\"vector\",", "            )", "            seed_group_id = seed_row.syndication_group_id", "            assert recompute_calls == [], \"singleton creation must not recompute\"", "", "            row = await attach_article_to_group(", "                session,", "                article_id=later_attachee.id,", "                matched_article_id=current_primary.id,", "                similarity_score=0.86,", "                classification_method=\"vector\",", "                frozen_group_id=seed_group_id,", "            )", "            group_id = row.syndication_group_id", "", "            # The optimization invariant: skip the recompute because the new", "            # attachee (2026-04-05) is strictly later than the current primary", "            # (2026-04-04) and can't displace it.", "            assert recompute_calls == [], (", "                f\"expected zero recompute calls when new attachee can't displace; got {recompute_calls}\"", "            )", "", "            # Correctness invariant: primary stays as the earlier-dated article.", "            group = await session.get(SourceClassificationGroup, group_id)", "            assert group is not None", "            assert group.primary_article_id == current_primary.id", "    finally:", "        await api_helper.session.close()", "", "", "@pytest.mark.asyncio", "async def test_attach_runs_primary_recompute_when_new_member_is_earlier(", "    clean_article_tables, monkeypatch: pytest.MonkeyPatch", "):", "    \"\"\"Inverse of the skip case: when the new attachee's ``date_published``", "    is earlier than the current primary's, the full recompute must run and", "    update the group's primary. Locks in that the optimization isn't", "    over-eager about skipping.", "    \"\"\"", "    from microservices.web_extraction.services.helpers import source_classification as sc_mod", "", "    response_ids = await _seed_response_ids(2)", "    api_helper = APIHelper()", "    recompute_calls: list[UUID] = []", "", "    real_reevaluate = sc_mod.reevaluate_group_primary", "", "    async def _spy_reevaluate(db, syndication_group_id):", "        recompute_calls.append(syndication_group_id)", "        await real_reevaluate(db, syndication_group_id)", "", "    monkeypatch.setattr(sc_mod, \"reevaluate_group_primary\", _spy_reevaluate)", "", "    try:", "        async with sessionmanager_datalake.session() as session:", "            current_primary = Tables.Article()", "            earlier_attachee = Tables.Article()", "            session.add_all([current_primary, earlier_attachee])", "            await session.flush()", "            session.add_all(", "                [", "                    Tables.ZyteArticle(", "                        article_id=current_primary.id,", "                        response_id=response_ids[0],", "                        article_url=\"https://example.com/primary\",", "                        article_title=\"primary\",", "                        content=\"primary\",", "                        date_published=datetime(2026, 4, 5, tzinfo=timezone.utc),", "                    ),", "                    Tables.ZyteArticle(", "                        article_id=earlier_attachee.id,", "                        response_id=response_ids[1],", "                        article_url=\"https://example.com/earlier\",", "                        article_title=\"earlier\",", "                        content=\"earlier\",", "                        date_published=datetime(2026, 4, 4, tzinfo=timezone.utc),", "                    ),", "                ]", "            )", "            await session.commit()", "", "            seed_row = await attach_article_to_group(", "                session,", "                article_id=current_primary.id,", "                matched_article_id=None,", "                similarity_score=None,", "                classification_method=\"vector\",", "            )", "            seed_group_id = seed_row.syndication_group_id", "", "            row = await attach_article_to_group(", "                session,", "                article_id=earlier_attachee.id,", "                matched_article_id=current_primary.id,", "                similarity_score=0.86,", "                classification_method=\"vector\",", "                frozen_group_id=seed_group_id,", "            )", "            group_id = row.syndication_group_id", "", "            # Recompute MUST run when the new attachee is earlier.", "            assert recompute_calls == [group_id], (", "                f\"expected one recompute call when new attachee is earlier; got {recompute_calls}\"", "            )", "", "            # And the primary must flip to the earlier article.", "            group = await session.get(SourceClassificationGroup, group_id)", "            assert group is not None", "            assert group.primary_article_id == earlier_attachee.id", "    finally:", "        await api_helper.session.close()", "", "", "@pytest.mark.asyncio", "async def test_attach_skips_recompute_when_dated_primary_meets_undated_new_member(", "    clean_article_tables, monkeypatch: pytest.MonkeyPatch", "):", "    \"\"\"Manual-upload (no Zyte ``date_published``) attaching to a group whose", "    primary has a real publish date must skip the recompute \u2014 the", "    \"has-dated-row beats undated\" ordering in ``_pick_primary_article_id``", "    means an undated new member can never displace a dated primary.", "    \"\"\"", "    from microservices.web_extraction.services.helpers import source_classification as sc_mod", "", "    response_ids = await _seed_response_ids(1)", "    api_helper = APIHelper()", "    recompute_calls: list[UUID] = []", "", "    real_reevaluate = sc_mod.reevaluate_group_primary", "", "    async def _spy_reevaluate(db, syndication_group_id):", "        recompute_calls.append(syndication_group_id)", "        await real_reevaluate(db, syndication_group_id)", "", "    monkeypatch.setattr(sc_mod, \"reevaluate_group_primary\", _spy_reevaluate)", "", "    try:", "        async with sessionmanager_datalake.session() as session:", "            dated_primary = Tables.Article()", "            undated_attachee = Tables.Article()", "            session.add_all([dated_primary, undated_attachee])", "            await session.flush()", "            session.add(", "                Tables.ZyteArticle(", "                    article_id=dated_primary.id,", "                    response_id=response_ids[0],", "                    article_url=\"https://example.com/primary\",", "                    article_title=\"primary\",", "                    content=\"primary\",", "                    date_published=datetime(2026, 4, 5, tzinfo=timezone.utc),", "                )", "            )", "            # undated_attachee has no ZyteArticle row \u2014 simulates a manual upload.", "            await session.commit()", "", "            seed_row = await attach_article_to_group(", "                session,", "                article_id=dated_primary.id,", "                matched_article_id=None,", "                similarity_score=None,", "                classification_method=\"vector\",", "            )", "            seed_group_id = seed_row.syndication_group_id", "", "            row = await attach_article_to_group(", "                session,", "                article_id=undated_attachee.id,", "                matched_article_id=dated_primary.id,", "                similarity_score=0.86,", "                classification_method=\"vector\",", "                frozen_group_id=seed_group_id,", "            )", "            group_id = row.syndication_group_id", "", "            assert recompute_calls == [], (", "                f\"expected zero recompute calls when undated new member joins a dated-primary group; got {recompute_calls}\"", "            )", "            group = await session.get(SourceClassificationGroup, group_id)", "            assert group is not None", "            assert group.primary_article_id == dated_primary.id", "    finally:", "        await api_helper.session.close()", "", "", "@pytest.mark.asyncio", "async def test_crossed_concurrent_syndication_writes_do_not_deadlock(clean_article_tables):", "    response_ids = await _seed_response_ids(2)", "", "    async with sessionmanager_datalake.session() as seed_session:", "        article_a = Tables.Article()", "        article_b = Tables.Article()", "        seed_session.add_all([article_a, article_b])", "        await seed_session.flush()", "", "        seed_session.add_all(", "            [", "                Tables.ZyteArticle(", "                    article_id=article_a.id,", "                    response_id=response_ids[0],", "                    article_url=\"https://example.com/article-a\",", "                    article_title=\"article-a\",", "                    content=\"article-a\",", "                    date_published=datetime(2026, 4, 4, tzinfo=timezone.utc),", "                ),", "                Tables.ZyteArticle(", "                    article_id=article_b.id,", "                    response_id=response_ids[1],", "                    article_url=\"https://example.com/article-b\",", "                    article_title=\"article-b\",", "                    content=\"article-b\",", "                    date_published=datetime(2026, 4, 5, tzinfo=timezone.utc),", "                ),", "            ]", "        )", "        await seed_session.commit()", "        article_a_id = article_a.id", "        article_b_id = article_b.id", "", "    async def _write(", "        *,", "        current_article_id: UUID,", "        current_matched_article_id: UUID,", "        score: float,", "    ) -> UUID:", "        async with sessionmanager_datalake.session() as worker_session:", "            # Mirror the production flow: resolve/materialize the matched", "            # article's group first, then attach with that frozen group id.", "            frozen_group_id = await _resolve_or_materialize_group_for_article(", "                worker_session, current_matched_article_id", "            )", "            # _resolve_or_materialize_group_for_article does not commit (in", "            # production the immediately-following persist_layer_two_retry_context", "            # call commits both the singleton and the retry-context row in one", "            # transaction). The commit here releases the per-article advisory", "            # lock on the matched article so the subsequent attach can proceed", "            # without deadlocking on the crossed concurrent worker.", "            await worker_session.commit()", "            classification = await attach_article_to_group(", "                worker_session,", "                article_id=current_article_id,", "                matched_article_id=current_matched_article_id,", "                similarity_score=score,", "                classification_method=\"vector\",", "                frozen_group_id=frozen_group_id,", "            )", "            return classification.syndication_group_id", "", "    group_a, group_b = await asyncio.wait_for(", "        asyncio.gather(", "            _write(", "                current_article_id=article_a_id,", "                current_matched_article_id=article_b_id,", "                score=0.84,", "            ),", "            _write(", "                current_article_id=article_b_id,", "                current_matched_article_id=article_a_id,", "                score=0.85,", "            ),", "        ),", "        timeout=15,", "    )", "", "    async with sessionmanager_datalake.session() as verify_session:", "        rows = (", "            (", "                await verify_session.execute(", "                    select(SourceClassification).where(", "                        SourceClassification.article_id.in_([article_a_id, article_b_id])", "                    )", "                )", "            )", "            .scalars()", "            .all()", "        )", "        groups = (", "            (", "                await verify_session.execute(", "                    select(SourceClassificationGroup).where(", "                        SourceClassificationGroup.id.in_({group_a, group_b})", "                    )", "                )", "            )", "            .scalars()", "            .all()", "        )", "", "    # Two invariants under crossed concurrent writes:", "    #", "    # 1. No deadlock (asyncio.wait_for timeout above is the detector).", "    # 2. **Convergence**: both articles end up in the same group, even when", "    #    the workers each pre-resolve their own singleton between the other", "    #    worker's resolve and attach. ``attach_article_to_group`` catches the", "    #    divergence under the dual advisory lock and calls", "    #    ``_merge_syndication_groups`` to fold the two groups into one. The", "    #    losing group row is deleted; both classification rows now point at", "    #    the surviving (merged) group, and ``member_count`` reflects the", "    #    actual member set. See DAT-6369 for the design notes on this race.", "    assert len(rows) == 2", "    assert {row.article_id for row in rows} == {article_a_id, article_b_id}", "    group_ids = {row.syndication_group_id for row in rows}", "    assert len(group_ids) == 1, (", "        f\"crossed-write convergence broken \u2014 articles landed in different groups: {group_ids}\"", "    )", "    surviving_group_id = next(iter(group_ids))", "    assert surviving_group_id in {group_a, group_b}, (", "        \"surviving group must be one of the two pre-resolved groups (the merge winner)\"", "    )", "", "    # Exactly one of the two pre-resolved groups should still exist after", "    # the merge \u2014 the loser row is deleted.", "    surviving_groups = {g.id for g in groups}", "    assert surviving_groups == {surviving_group_id}, (", "        f\"expected only winner group {surviving_group_id} to remain after merge; \"", "        f\"saw {surviving_groups}\"", "    )", "    [winner] = groups", "    assert winner.member_count == 2, (", "        f\"merged group must reflect actual member count; got {winner.member_count}\"", "    )", "    assert winner.primary_article_id in {article_a_id, article_b_id}", "", "", "@pytest.mark.asyncio", "async def test_attach_article_to_group_with_frozen_group_id_attaches_to_existing(", "    clean_article_tables,", "):", "    \"\"\"Retry-recovery freeze path: attach using a pre-resolved group id.\"\"\"", "    response_ids = await _seed_response_ids(2)", "    async with sessionmanager_datalake.session() as session:", "        seed_article = Tables.Article()", "        joining_article = Tables.Article()", "        session.add_all([seed_article, joining_article])", "        await session.flush()", "", "        session.add_all(", "            [", "                Tables.ZyteArticle(", "                    article_id=seed_article.id,", "                    response_id=response_ids[0],", "                    article_url=\"https://example.com/seed\",", "                    article_title=\"seed\",", "                    content=\"seed\",", "                    date_published=datetime(2026, 4, 4, tzinfo=timezone.utc),", "                ),", "                Tables.ZyteArticle(", "                    article_id=joining_article.id,", "                    response_id=response_ids[1],", "                    article_url=\"https://example.com/joining\",", "                    article_title=\"joining\",", "                    content=\"joining\",", "                    date_published=datetime(2026, 4, 5, tzinfo=timezone.utc),", "                ),", "            ]", "        )", "        await session.flush()", "", "        existing_group_id = uuid4()", "        session.add(", "            SourceClassificationGroup(", "                id=existing_group_id,", "                primary_article_id=seed_article.id,", "                seed_article_id=seed_article.id,", "                member_count=1,", "            )", "        )", "        await session.flush()", "        session.add(", "            SourceClassification(", "                article_id=seed_article.id,", "                syndication_group_id=existing_group_id,", "                similarity_score=None,", "                matched_article_id=None,", "                classification_method=\"vector\",", "            )", "        )", "        await session.commit()", "", "        classification_row = await attach_article_to_group(", "            session,", "            article_id=joining_article.id,", "            matched_article_id=None,", "            similarity_score=None,", "            classification_method=\"vector\",", "            frozen_group_id=existing_group_id,", "        )", "", "        assert classification_row.syndication_group_id == existing_group_id", "        group = await session.get(SourceClassificationGroup, existing_group_id)", "        assert group is not None", "        assert group.member_count == 2", "        # Seed must remain the original seed \u2014 frozen path doesn't reseed.", "        assert group.seed_article_id == seed_article.id", "", "", "@pytest.mark.asyncio", "async def test_attach_article_to_group_with_frozen_group_id_raises_when_missing(", "    clean_article_tables,", "):", "    \"\"\"Frozen group id pointing at a non-existent group must raise loudly.\"\"\"", "    response_ids = await _seed_response_ids(1)", "    async with sessionmanager_datalake.session() as session:", "        article = Tables.Article()", "        session.add(article)", "        await session.flush()", "        session.add(", "            Tables.ZyteArticle(", "                article_id=article.id,", "                response_id=response_ids[0],", "                article_url=\"https://example.com/article\",", "                article_title=\"article\",", "                content=\"article\",", "                date_published=datetime(2026, 4, 4, tzinfo=timezone.utc),", "            )", "        )", "        await session.commit()", "", "        with pytest.raises(DatabaseWriteException):", "            await attach_article_to_group(", "                session,", "                article_id=article.id,", "                matched_article_id=None,", "                similarity_score=None,", "                classification_method=\"vector\",", "                frozen_group_id=uuid4(),", "            )", "", "", "@pytest.mark.asyncio", "async def test_attach_article_to_group_rejects_matched_without_frozen_group(", "    clean_article_tables,", "):", "    \"\"\"matched_article_id without frozen_group_id violates the contract.", "", "    Production resolves the target group via resolve_retry_syndication_group_id", "    before attaching, so reaching attach_article_to_group with matched_article_id", "    but no frozen_group_id indicates a caller bug.", "    \"\"\"", "    response_ids = await _seed_response_ids(1)", "    async with sessionmanager_datalake.session() as session:", "        article = Tables.Article()", "        matched = Tables.Article()", "        session.add_all([article, matched])", "        await session.flush()", "        session.add(", "            Tables.ZyteArticle(", "                article_id=article.id,", "                response_id=response_ids[0],", "                article_url=\"https://example.com/article\",", "                article_title=\"article\",", "                content=\"article\",", "                date_published=datetime(2026, 4, 4, tzinfo=timezone.utc),", "            )", "        )", "        await session.commit()", "", "        with pytest.raises(DatabaseWriteException):", "            await attach_article_to_group(", "                session,", "                article_id=article.id,", "                matched_article_id=matched.id,", "                similarity_score=0.9,", "                classification_method=\"vector\",", "                frozen_group_id=None,", "            )", "", "", "@pytest.mark.asyncio", "async def test_attach_article_to_group_persists_match_info_on_join_path(", "    clean_article_tables,", "):", "    \"\"\"``match_info`` passed on the join path must land on", "    ``source_classifications.match_info`` (JSONB). Carries dedup chunk", "    details + any borderline-verifier verdict so analytics can answer", "    \"why was this classified as syndication\" without joining to logs.", "    \"\"\"", "    response_ids = await _seed_response_ids(2)", "    async with sessionmanager_datalake.session() as session:", "        matched_article = Tables.Article()", "        new_article = Tables.Article()", "        session.add_all([matched_article, new_article])", "        await session.flush()", "        session.add_all(", "            [", "                Tables.ZyteArticle(", "                    article_id=matched_article.id,", "                    response_id=response_ids[0],", "                    article_url=\"https://example.com/matched\",", "                    article_title=\"matched\",", "                    content=\"matched\",", "                    date_published=datetime(2026, 4, 5, tzinfo=timezone.utc),", "                ),", "                Tables.ZyteArticle(", "                    article_id=new_article.id,", "                    response_id=response_ids[1],", "                    article_url=\"https://example.com/new\",", "                    article_title=\"new\",", "                    content=\"new\",", "                    date_published=datetime(2026, 4, 6, tzinfo=timezone.utc),", "                ),", "            ]", "        )", "        await session.commit()", "", "        # Singleton the matched article so we have a frozen_group_id to join.", "        matched_singleton = await attach_article_to_group(", "            session,", "            article_id=matched_article.id,", "            matched_article_id=None,", "            similarity_score=None,", "            classification_method=CLASSIFICATION_METHOD_VECTOR,", "        )", "        group_id = matched_singleton.syndication_group_id", "", "        match_info_payload = {", "            \"matched_chunk_index\": 3,", "            \"incoming_chunk_index\": 1,", "            \"llm_band\": \"duplicate_syndication\",", "            \"llm_verdict\": {\"event\": \"same\", \"verbatim\": False, \"reason\": \"rewritten\"},", "            \"llm_model\": \"gpt-5.4-nano\",", "        }", "", "        joined = await attach_article_to_group(", "            session,", "            article_id=new_article.id,", "            matched_article_id=matched_article.id,", "            similarity_score=0.92,", "            classification_method=CLASSIFICATION_METHOD_VECTOR,", "            frozen_group_id=group_id,", "            match_info=match_info_payload,", "        )", "", "        assert joined.syndication_group_id == group_id", "", "        # Re-read from the DB to confirm the JSONB column round-trips.", "        persisted = (", "            await session.execute(", "                select(SourceClassification).where(", "                    SourceClassification.article_id == new_article.id", "                )", "            )", "        ).scalar_one()", "        assert persisted.match_info == match_info_payload", "", "        # Singleton row for the matched article \u2014 created without match_info,", "        # so it must be NULL on the matched-article row (or absent from JSONB).", "        matched_row = (", "            await session.execute(", "                select(SourceClassification).where(", "                    SourceClassification.article_id == matched_article.id", "                )", "            )", "        ).scalar_one()", "        assert matched_row.match_info is None", "", "", "@pytest.mark.asyncio", "async def test_attach_article_to_group_singleton_path_ignores_match_info(", "    clean_article_tables,", "):", "    \"\"\"``match_info`` on the singleton-creation path is documented as a no-op", "    (no match to record). Per the helper docstring, the column stays NULL", "    even when callers pass a payload by mistake \u2014 locks in the docstring", "    contract so a future regression can't silently start persisting noise", "    onto singleton seed rows.", "    \"\"\"", "    response_ids = await _seed_response_ids(1)", "    async with sessionmanager_datalake.session() as session:", "        article = Tables.Article()", "        session.add(article)", "        await session.flush()", "        session.add(", "            Tables.ZyteArticle(", "                article_id=article.id,", "                response_id=response_ids[0],", "                article_url=\"https://example.com/seed\",", "                article_title=\"seed\",", "                content=\"seed\",", "                date_published=datetime(2026, 4, 4, tzinfo=timezone.utc),", "            )", "        )", "        await session.commit()", "", "        singleton = await attach_article_to_group(", "            session,", "            article_id=article.id,", "            matched_article_id=None,", "            similarity_score=None,", "            classification_method=CLASSIFICATION_METHOD_VECTOR,", "            match_info={\"this\": \"should not persist\"},", "        )", "", "        persisted = (", "            await session.execute(", "                select(SourceClassification).where(SourceClassification.article_id == article.id)", "            )", "        ).scalar_one()", "        assert persisted.match_info is None", "        assert singleton.syndication_group_id is not None", "", "", "@pytest.mark.asyncio", "async def test_attach_article_to_group_merges_groups_on_matched_divergence(", "    clean_article_tables,", "):", "    \"\"\"When the matched article's current group differs from ``frozen_group_id``,", "    ``attach_article_to_group`` must merge the two groups under one canonical", "    rather than fragmenting into separate clusters.", "", "    Setup mirrors the crossed-write race outcome deterministically: pre-create", "    two singleton groups (one per article), then call attach with a", "    ``frozen_group_id`` that points at one of them while ``matched_article_id``", "    is the article that lives in the other. The expected behaviour is that", "    the two groups are merged (lower-UUID-by-string wins), the loser row is", "    deleted, and the attached article lands in the surviving group.", "    \"\"\"", "    response_ids = await _seed_response_ids(3)", "    async with sessionmanager_datalake.session() as session:", "        matched_article = Tables.Article()", "        incoming_article = Tables.Article()", "        session.add_all([matched_article, incoming_article])", "        await session.flush()", "        session.add_all(", "            [", "                Tables.ZyteArticle(", "                    article_id=matched_article.id,", "                    response_id=response_ids[0],", "                    article_url=\"https://example.com/matched\",", "                    article_title=\"matched\",", "                    content=\"matched\",", "                    date_published=datetime(2026, 4, 5, tzinfo=timezone.utc),", "                ),", "                Tables.ZyteArticle(", "                    article_id=incoming_article.id,", "                    response_id=response_ids[1],", "                    article_url=\"https://example.com/incoming\",", "                    article_title=\"incoming\",", "                    content=\"incoming\",", "                    date_published=datetime(2026, 4, 6, tzinfo=timezone.utc),", "                ),", "            ]", "        )", "        await session.commit()", "", "        # Step 1: singleton the matched article. This produces G_match.", "        matched_singleton = await attach_article_to_group(", "            session,", "            article_id=matched_article.id,", "            matched_article_id=None,", "            similarity_score=None,", "            classification_method=CLASSIFICATION_METHOD_VECTOR,", "        )", "        g_match = matched_singleton.syndication_group_id", "", "        # Step 2: simulate the crossed-write race by hand \u2014 create G_alt as a", "        # bare group (no members yet) that a hypothetical concurrent worker", "        # might have produced. The merge target on the attach call below will", "        # be G_alt; the attach must detect that matched_article is actually", "        # in G_match (not G_alt) and merge the two groups.", "        g_alt_uuid = uuid4()", "        session.add(", "            SourceClassificationGroup(", "                id=g_alt_uuid,", "                primary_article_id=incoming_article.id,", "                seed_article_id=incoming_article.id,", "                member_count=0,", "            )", "        )", "        await session.commit()", "", "        # Step 3: attach incoming_article with frozen_group_id=G_alt, matched=matched_article.", "        # The merge fires because matched_article is in G_match, not G_alt.", "        joined = await attach_article_to_group(", "            session,", "            article_id=incoming_article.id,", "            matched_article_id=matched_article.id,", "            similarity_score=0.88,", "            classification_method=CLASSIFICATION_METHOD_VECTOR,", "            frozen_group_id=g_alt_uuid,", "        )", "", "        # Determinism: lower-UUID wins.", "        winner_id, loser_id = sorted([g_match, g_alt_uuid], key=str)", "", "        assert joined.syndication_group_id == winner_id, (", "            f\"attach must land in the merged-winner group; got {joined.syndication_group_id}, \"", "            f\"expected {winner_id}\"", "        )", "", "        # Both articles' classification rows now point at the winner.", "        rows = (", "            (", "                await session.execute(", "                    select(SourceClassification).where(", "                        SourceClassification.article_id.in_(", "                            [matched_article.id, incoming_article.id]", "                        )", "                    )", "                )", "            )", "            .scalars()", "            .all()", "        )", "        assert len(rows) == 2", "        assert {row.syndication_group_id for row in rows} == {winner_id}", "", "        # The loser group row was deleted by the merge.", "        surviving_group_ids = (", "            (", "                await session.execute(", "                    select(SourceClassificationGroup.id).where(", "                        SourceClassificationGroup.id.in_([g_match, g_alt_uuid])", "                    )", "                )", "            )", "            .scalars()", "            .all()", "        )", "        assert set(surviving_group_ids) == {winner_id}, (", "            f\"loser group {loser_id} must be deleted after merge; survivors: {surviving_group_ids}\"", "        )", "", "        winner_group = await session.get(SourceClassificationGroup, winner_id)", "        assert winner_group is not None", "        assert winner_group.member_count == 2", "        assert winner_group.primary_article_id in {matched_article.id, incoming_article.id}", "", "", "@pytest.mark.asyncio", "async def test_attach_article_to_group_merge_is_idempotent_across_concurrent_attempts(", "    clean_article_tables,", "):", "    \"\"\"Two concurrent attaches that both want to merge the same group pair", "    must converge cleanly: the second arriving worker either no-ops (the", "    merge already happened) or returns the same surviving group. The", "    deterministic lower-UUID-by-string winner choice plus FOR UPDATE on", "    both groups in id order is what serializes this.", "    \"\"\"", "    response_ids = await _seed_response_ids(3)", "    async with sessionmanager_datalake.session() as session:", "        matched_article = Tables.Article()", "        incoming_a = Tables.Article()", "        incoming_b = Tables.Article()", "        session.add_all([matched_article, incoming_a, incoming_b])", "        await session.flush()", "        session.add_all(", "            [", "                Tables.ZyteArticle(", "                    article_id=matched_article.id,", "                    response_id=response_ids[0],", "                    article_url=\"https://example.com/matched\",", "                    article_title=\"matched\",", "                    content=\"matched\",", "                    date_published=datetime(2026, 4, 5, tzinfo=timezone.utc),", "                ),", "                Tables.ZyteArticle(", "                    article_id=incoming_a.id,", "                    response_id=response_ids[1],", "                    article_url=\"https://example.com/incoming-a\",", "                    article_title=\"incoming-a\",", "                    content=\"incoming-a\",", "                    date_published=datetime(2026, 4, 6, tzinfo=timezone.utc),", "                ),", "                Tables.ZyteArticle(", "                    article_id=incoming_b.id,", "                    response_id=response_ids[2],", "                    article_url=\"https://example.com/incoming-b\",", "                    article_title=\"incoming-b\",", "                    content=\"incoming-b\",", "                    date_published=datetime(2026, 4, 7, tzinfo=timezone.utc),", "                ),", "            ]", "        )", "        await session.commit()", "", "        matched_singleton = await attach_article_to_group(", "            session,", "            article_id=matched_article.id,", "            matched_article_id=None,", "            similarity_score=None,", "            classification_method=CLASSIFICATION_METHOD_VECTOR,", "        )", "        g_match = matched_singleton.syndication_group_id", "", "        # Pre-create the \"alt\" group that both concurrent workers will try", "        # to merge with G_match.", "        g_alt_uuid = uuid4()", "        session.add(", "            SourceClassificationGroup(", "                id=g_alt_uuid,", "                primary_article_id=incoming_a.id,", "                seed_article_id=incoming_a.id,", "                member_count=0,", "            )", "        )", "        await session.commit()", "", "    # Two workers, both want to attach to G_alt with matched=matched_article.", "    # Both will detect divergence (matched is in G_match, not G_alt) and try", "    # to merge. One wins; the other observes the already-merged state.", "    async def _worker(incoming_article_id: UUID, score: float) -> UUID:", "        async with sessionmanager_datalake.session() as worker_session:", "            classification = await attach_article_to_group(", "                worker_session,", "                article_id=incoming_article_id,", "                matched_article_id=matched_article.id,", "                similarity_score=score,", "                classification_method=CLASSIFICATION_METHOD_VECTOR,", "                frozen_group_id=g_alt_uuid,", "            )", "            return classification.syndication_group_id", "", "    group_a, group_b = await asyncio.wait_for(", "        asyncio.gather(", "            _worker(incoming_a.id, 0.86),", "            _worker(incoming_b.id, 0.87),", "        ),", "        timeout=15,", "    )", "", "    # Both workers converge on the same surviving group, which is the", "    # lower-UUID-by-string of the two pre-existing groups.", "    assert group_a == group_b, (", "        f\"concurrent merges must converge on the same group; got {group_a} vs {group_b}\"", "    )", "    winner_id = group_a", "    expected_winner = min([g_match, g_alt_uuid], key=str)", "    assert winner_id == expected_winner", "", "    async with sessionmanager_datalake.session() as verify_session:", "        rows = (", "            (", "                await verify_session.execute(", "                    select(SourceClassification).where(", "                        SourceClassification.article_id.in_(", "                            [matched_article.id, incoming_a.id, incoming_b.id]", "                        )", "                    )", "                )", "            )", "            .scalars()", "            .all()", "        )", "        assert {row.syndication_group_id for row in rows} == {winner_id}", "        winner_group = await verify_session.get(SourceClassificationGroup, winner_id)", "        assert winner_group is not None", "        assert winner_group.member_count == 3", "", "", "# ---------------------------------------------------------------------------", "# Title/headline blocking key (DAT-7932) \u2014 end-to-end recall + precision", "# ---------------------------------------------------------------------------", "", "", "_BLOCKING_HEADLINE = \"Regional water authority approves new desalination plant funding\"", "", "", "def _incoming_article(*, headline: str, url: str, date_published: datetime) -> ArticleSchema:", "    \"\"\"Build an incoming L2 ArticleSchema for the classification chain.\"\"\"", "    return ArticleSchema(", "        source=\"ZYTE\",", "        raw_response=RawAPIResponse(status_code=200, headers={}, source=\"ZYTE\", body={\"d\": \"b\"}),", "        article_data=ArticleItem(", "            url=url,", "            headline=headline,", "            content=\"incoming body\",", "            date_published=date_published,", "        ),", "        article_url=url,", "    )", "", "", "def _diluted_incoming_chunks() -> ChunkVectors:", "    \"\"\"One chunk matching a candidate at ~0.85 (above floor, below the 0.92", "    absolute-count signal) plus one orthogonal chrome chunk that is dropped \u2014", "    the aggregate coverage score lands UNIQUE, so only the title blocking key", "    can rescue it.", "    \"\"\"", "    return ChunkVectors(", "        chunks=[", "            ChunkEmbedding(", "                chunk_index=0,", "                chunk_text=\"matching body\",", "                token_count=8,", "                embedding=_embedding(0.85, sqrt(1 - 0.85**2)),", "            ),", "            ChunkEmbedding(", "                chunk_index=1,", "                chunk_text=\"chrome / related links\",", "                token_count=8,", "                embedding=_embedding(0.0, 1.0),", "            ),", "        ]", "    )", "", "", "def _pin_blocking_config(monkeypatch: pytest.MonkeyPatch) -> None:", "    \"\"\"Pin the blocking key on and the verifier OFF so these tests isolate the", "    promotion path from LLM adjudication.", "", "    The verifier is enabled in deployed environments; pinning it off here is a test", "    isolation choice, not a statement about production. These cases assert what the", "    blocking key promotes, and a live LLM call would both adjudicate the promotion", "    away and put network I/O in the test path. Verifier adjudication of a promotion", "    is covered separately by", "    ``test_verifier_demotes_title_blocking_promotion_on_different_event``.", "", "    The mid-band bounds are pinned too so a change to the production defaults cannot", "    shift which band these scores land in.", "    \"\"\"", "    monkeypatch.setattr(web_config, \"DEDUP_VERIFIER_ENABLED\", False)", "    monkeypatch.setattr(web_config, \"DEDUP_TITLE_BLOCKING_ENABLED\", True)", "    monkeypatch.setattr(web_config, \"DEDUP_TITLE_BLOCKING_MIN_WORDS\", 5)", "    monkeypatch.setattr(web_config, \"DEDUP_VERIFIER_MID_BAND_LOW\", 0.82)", "    monkeypatch.setattr(web_config, \"DEDUP_VERIFIER_MID_BAND_HIGH\", 0.90)", "", "", "async def _classify_and_maybe_attach(", "    session,", "    api_helper: APIHelper,", "    *,", "    incoming_article: ArticleSchema,", "    incoming_article_id: UUID,", "    incoming_response_id: UUID,", "    incoming_chunks: ChunkVectors,", "):", "    \"\"\"Run the classification chain and write the incoming article's", "    classification row, mirroring the L2 orchestrator's canonical path.", "", "    A syndicated plan joins its resolved group and carries ``match_info``; every", "    other non-duplicate plan creates a singleton and carries", "    ``rejected_match_info`` instead, so a UNIQUE outcome's verifier adjudication", "    reaches the DB the same way it does in production.", "    \"\"\"", "    activity_id = await session.scalar(", "        select(WebExtractionResponse.layer_two_activity_id).where(", "            WebExtractionResponse.id == incoming_response_id", "        )", "    )", "    plan = await classify_layer_two_article(", "        session,", "        api_helper,", "        article=incoming_article,", "        article_markdown=\"incoming body markdown\",", "        chunk_vectors=incoming_chunks,", "        activity_id=activity_id,", "        response_id=incoming_response_id,", "        retry_context=LayerTwoRetryContext.first_attempt(),", "        api_key=\"sk-test\",", "    )", "    if plan.is_duplicate:", "        return plan", "    matched_for_attach = None", "    if plan.is_syndicated:", "        assert plan.best_match is not None", "        matched_for_attach = plan.best_match.article_id", "    await attach_article_to_group(", "        session,", "        article_id=incoming_article_id,", "        matched_article_id=matched_for_attach,", "        similarity_score=plan.similarity_score if matched_for_attach is not None else None,", "        classification_method=plan.classification_method,", "        frozen_group_id=plan.resolved_retry_group_id,", "        match_info=plan.match_info if matched_for_attach is not None else None,", "        rejected_match_info=plan.rejected_match_info,", "    )", "    return plan", "", "", "async def _seed_candidate_and_incoming(", "    *,", "    candidate_headline: str,", "    candidate_url: str,", "    incoming_headline: str,", "    response_ids: list[UUID],", ") -> tuple[UUID, UUID]:", "    \"\"\"Seed a candidate article (chunks + zyte row) and an incoming zyte row.", "", "    The incoming article's chunks are intentionally NOT written \u2014 they are", "    supplied in-memory to ``deduplicate_article`` so there is no self-match.", "", "    :returns: ``(candidate_id, incoming_id)``.", "    \"\"\"", "    async with sessionmanager_datalake.session() as session:", "        candidate = Tables.Article()", "        incoming = Tables.Article()", "        session.add_all([candidate, incoming])", "        await session.flush()", "        # Two identical axis-0 chunks: the diluted incoming chunk matches them at", "        # ~0.85 (one covered incoming chunk of two \u2192 UNIQUE-band coverage).", "        session.add_all(", "            [", "                Tables.ArticleChunk(", "                    article_id=candidate.id,", "                    chunk_index=0,", "                    chunk_text=\"candidate body a\",", "                    embedding=_embedding(1.0, 0.0),", "                ),", "                Tables.ArticleChunk(", "                    article_id=candidate.id,", "                    chunk_index=1,", "                    chunk_text=\"candidate body b\",", "                    embedding=_embedding(1.0, 0.0),", "                ),", "            ]", "        )", "        session.add_all(", "            [", "                Tables.ZyteArticle(", "                    article_id=candidate.id,", "                    response_id=response_ids[0],", "                    article_url=candidate_url,", "                    article_title=candidate_headline,", "                    content=\"candidate content\",", "                    date_published=datetime(2026, 4, 5, tzinfo=timezone.utc),", "                ),", "                Tables.ZyteArticle(", "                    article_id=incoming.id,", "                    response_id=response_ids[1],", "                    article_url=\"https://paper-b.example/story\",", "                    article_title=incoming_headline,", "                    content=\"incoming content\",", "                    date_published=datetime(2026, 4, 6, tzinfo=timezone.utc),", "                ),", "            ]", "        )", "        await session.commit()", "        return candidate.id, incoming.id", "", "", "@pytest.mark.asyncio", "async def test_title_blocking_key_unifies_verbatim_headline_cross_publisher(", "    clean_article_tables, monkeypatch", "):", "    \"\"\"Recall: two cross-publisher copies with the SAME headline but a", "    chrome-diluted body (score in the UNIQUE band) end up in ONE syndication", "    group \u2014 before the blocking key they fragmented into two singletons.", "    \"\"\"", "    _pin_blocking_config(monkeypatch)", "    response_ids = await _seed_response_ids(2)", "    candidate_id, incoming_id = await _seed_candidate_and_incoming(", "        candidate_headline=_BLOCKING_HEADLINE,", "        candidate_url=\"https://wire-a.example/story\",", "        incoming_headline=_BLOCKING_HEADLINE,", "        response_ids=response_ids,", "    )", "", "    api_helper = APIHelper()", "    try:", "        async with sessionmanager_datalake.session() as session:", "            plan = await _classify_and_maybe_attach(", "                session,", "                api_helper,", "                incoming_article=_incoming_article(", "                    headline=_BLOCKING_HEADLINE,", "                    url=\"https://paper-b.example/story\",", "                    date_published=datetime(2026, 4, 6, tzinfo=timezone.utc),", "                ),", "                incoming_article_id=incoming_id,", "                incoming_response_id=response_ids[1],", "                incoming_chunks=_diluted_incoming_chunks(),", "            )", "    finally:", "        await api_helper.session.close()", "", "    assert plan.classification == DeduplicationClassification.SYNDICATION_CANDIDATE", "    assert plan.match_info[\"title_blocking_key\"][\"verifier_forced\"] is True", "", "    async with sessionmanager_datalake.session() as verify:", "        rows = (", "            (", "                await verify.execute(", "                    select(SourceClassification).where(", "                        SourceClassification.article_id.in_([candidate_id, incoming_id])", "                    )", "                )", "            )", "            .scalars()", "            .all()", "        )", "    assert len(rows) == 2", "    group_ids = {row.syndication_group_id for row in rows}", "    assert len(group_ids) == 1, (", "        f\"verbatim-headline pair must share one syndication group; got {group_ids}\"", "    )", "", "", "@pytest.mark.asyncio", "async def test_title_blocking_key_control_pair_different_headline_stays_unique(", "    clean_article_tables, monkeypatch", "):", "    \"\"\"Precision: a diluted pair whose headlines DIFFER is not force-grouped by", "    the blocking key \u2014 it stays UNIQUE (no title_blocking_key promotion).", "    \"\"\"", "    _pin_blocking_config(monkeypatch)", "    response_ids = await _seed_response_ids(2)", "    candidate_id, incoming_id = await _seed_candidate_and_incoming(", "        candidate_headline=\"City council debates downtown parking overhaul plan\",", "        candidate_url=\"https://wire-a.example/story\",", "        incoming_headline=_BLOCKING_HEADLINE,", "        response_ids=response_ids,", "    )", "", "    api_helper = APIHelper()", "    try:", "        async with sessionmanager_datalake.session() as session:", "            plan = await _classify_and_maybe_attach(", "                session,", "                api_helper,", "                incoming_article=_incoming_article(", "                    headline=_BLOCKING_HEADLINE,", "                    url=\"https://paper-b.example/story\",", "                    date_published=datetime(2026, 4, 6, tzinfo=timezone.utc),", "                ),", "                incoming_article_id=incoming_id,", "                incoming_response_id=response_ids[1],", "                incoming_chunks=_diluted_incoming_chunks(),", "            )", "    finally:", "        await api_helper.session.close()", "", "    assert plan.classification == DeduplicationClassification.UNIQUE", "    assert plan.best_match is None", "    assert \"title_blocking_key\" not in plan.match_info", "", "", "@pytest.mark.asyncio", "async def test_verifier_demotes_title_blocking_promotion_on_different_event(", "    clean_article_tables, monkeypatch", "):", "    \"\"\"Precision: with the verifier LIVE (as it is in deployed environments), a", "    ``different`` verdict demotes a title-blocking promotion back to UNIQUE and", "    clears its lineage.", "", "    This is the recall/precision trade the verifier exists to make: every promotion", "    carries ``verifier_forced``, so enabling the verifier hands each one to the LLM", "    and a rejection undoes it. The LLM call is stubbed \u2014 no transport runs.", "    \"\"\"", "    _pin_blocking_config(monkeypatch)", "    monkeypatch.setattr(web_config, \"DEDUP_VERIFIER_ENABLED\", True)", "", "    async def _fake_llm(api_helper, **kwargs):", "        return {\"event\": \"different\", \"verbatim\": None, \"reason\": \"distinct events\"}, \"stub-model\"", "", "    monkeypatch.setattr(borderline_verifier, \"_call_llm_verifier\", _fake_llm)", "", "    response_ids = await _seed_response_ids(2)", "    _candidate_id, incoming_id = await _seed_candidate_and_incoming(", "        candidate_headline=_BLOCKING_HEADLINE,", "        candidate_url=\"https://wire-a.example/story\",", "        incoming_headline=_BLOCKING_HEADLINE,", "        response_ids=response_ids,", "    )", "", "    api_helper = APIHelper()", "    try:", "        async with sessionmanager_datalake.session() as session:", "            plan = await _classify_and_maybe_attach(", "                session,", "                api_helper,", "                incoming_article=_incoming_article(", "                    headline=_BLOCKING_HEADLINE,", "                    url=\"https://paper-b.example/story\",", "                    date_published=datetime(2026, 4, 6, tzinfo=timezone.utc),", "                ),", "                incoming_article_id=incoming_id,", "                incoming_response_id=response_ids[1],", "                incoming_chunks=_diluted_incoming_chunks(),", "            )", "    finally:", "        await api_helper.session.close()", "", "    # The promotion happened (the headline matched cross-publisher) and was then", "    # adjudicated away, so the plan must carry no residual matched lineage.", "    assert plan.classification == DeduplicationClassification.UNIQUE", "    assert plan.best_match is None", "    assert plan.match_info == {}", "", "", "@pytest.mark.asyncio", "async def test_title_blocking_key_same_publisher_not_force_grouped(", "    clean_article_tables, monkeypatch", "):", "    \"\"\"Precision: an identical-headline pair from the SAME publisher is not a", "    syndication \u2014 the blocking key must not promote it.", "    \"\"\"", "    _pin_blocking_config(monkeypatch)", "    response_ids = await _seed_response_ids(2)", "    candidate_id, incoming_id = await _seed_candidate_and_incoming(", "        candidate_headline=_BLOCKING_HEADLINE,", "        # Same host as the incoming article below.", "        candidate_url=\"https://paper-b.example/older-story\",", "        incoming_headline=_BLOCKING_HEADLINE,", "        response_ids=response_ids,", "    )", "", "    api_helper = APIHelper()", "    try:", "        async with sessionmanager_datalake.session() as session:", "            plan = await _classify_and_maybe_attach(", "                session,", "                api_helper,", "                incoming_article=_incoming_article(", "                    headline=_BLOCKING_HEADLINE,", "                    url=\"https://paper-b.example/story\",", "                    date_published=datetime(2026, 4, 6, tzinfo=timezone.utc),", "                ),", "                incoming_article_id=incoming_id,", "                incoming_response_id=response_ids[1],", "                incoming_chunks=_diluted_incoming_chunks(),", "            )", "    finally:", "        await api_helper.session.close()", "", "    assert plan.classification == DeduplicationClassification.UNIQUE", "    assert plan.best_match is None", "    assert \"title_blocking_key\" not in plan.match_info", "", "", "# ---------------------------------------------------------------------------", "# Same-publisher demote \u2014 end-to-end persistence of both outcomes", "# ---------------------------------------------------------------------------", "", "_DEMOTE_HEADLINE = \"Regional water authority approves new desalination plant funding\"", "", "# One incoming chunk at cos 0.85 against the candidate's chunks: full coverage at", "# 0.85 puts the aggregate score above the syndication threshold and inside the", "# verifier's mid band, which is where the same-publisher demote is eligible.", "_MID_BAND_SIMILARITY = 0.85", "", "", "def _pin_demote_config(monkeypatch: pytest.MonkeyPatch, *, enforce: bool) -> None:", "    \"\"\"Pin the verifier live, the demote's enforcement, and the mid-band bounds.", "", "    The title blocking key is pinned OFF: it is cross-publisher only, so it cannot", "    fire on these pairs anyway, and turning it off keeps the promotion path out of", "    the assertions. Band bounds are pinned so a change to the production defaults", "    cannot shift which band these scores land in.", "    \"\"\"", "    monkeypatch.setattr(web_config, \"DEDUP_VERIFIER_ENABLED\", True)", "    monkeypatch.setattr(web_config, \"DEDUP_SAME_PUBLISHER_ENFORCE\", enforce)", "    monkeypatch.setattr(web_config, \"DEDUP_TITLE_BLOCKING_ENABLED\", False)", "    monkeypatch.setattr(web_config, \"DEDUP_VERIFIER_MID_BAND_LOW\", 0.82)", "    monkeypatch.setattr(web_config, \"DEDUP_VERIFIER_MID_BAND_HIGH\", 0.90)", "", "", "def _stub_verdict(monkeypatch: pytest.MonkeyPatch, verdict: dict) -> None:", "    \"\"\"Return a fixed verifier verdict without running any transport.\"\"\"", "", "    async def _fake_llm(api_helper, **kwargs):", "        return verdict, \"stub-model\"", "", "    monkeypatch.setattr(borderline_verifier, \"_call_llm_verifier\", _fake_llm)", "", "", "def _mid_band_incoming_chunks() -> ChunkVectors:", "    \"\"\"One chunk matching every candidate chunk at ``_MID_BAND_SIMILARITY``.\"\"\"", "    return _chunk_vectors(_MID_BAND_SIMILARITY, sqrt(1 - _MID_BAND_SIMILARITY**2))", "", "", "async def _seed_same_publisher_pair(", "    *,", "    candidate_url: str,", "    response_ids: list[UUID],", ") -> tuple[UUID, UUID]:", "    \"\"\"Seed a candidate with ONE chunk, plus an incoming zyte row.", "", "    A single candidate chunk matters: coverage divides by the larger side's chunk", "    count, so the two-chunk candidate ``_seed_candidate_and_incoming`` builds halves", "    the aggregate score to ~0.43 and lands out of every verifier band. One chunk on", "    each side keeps the score at the pair's raw similarity, which is what puts it in", "    the mid band where the demote is eligible.", "", "    :returns: ``(candidate_id, incoming_id)``.", "    \"\"\"", "    async with sessionmanager_datalake.session() as session:", "        candidate = Tables.Article()", "        incoming = Tables.Article()", "        session.add_all([candidate, incoming])", "        await session.flush()", "        session.add(", "            Tables.ArticleChunk(", "                article_id=candidate.id,", "                chunk_index=0,", "                chunk_text=\"candidate body\",", "                embedding=_embedding(1.0, 0.0),", "            )", "        )", "        session.add_all(", "            [", "                Tables.ZyteArticle(", "                    article_id=candidate.id,", "                    response_id=response_ids[0],", "                    article_url=candidate_url,", "                    article_title=_DEMOTE_HEADLINE,", "                    content=\"candidate content\",", "                    date_published=datetime(2026, 4, 5, tzinfo=timezone.utc),", "                ),", "                Tables.ZyteArticle(", "                    article_id=incoming.id,", "                    response_id=response_ids[1],", "                    article_url=\"https://paper-b.example/story\",", "                    article_title=_DEMOTE_HEADLINE,", "                    content=\"incoming content\",", "                    date_published=datetime(2026, 4, 6, tzinfo=timezone.utc),", "                ),", "            ]", "        )", "        await session.commit()", "        return candidate.id, incoming.id", "", "", "async def _classification_row(article_id: UUID) -> SourceClassification:", "    async with sessionmanager_datalake.session() as verify:", "        return (", "            await verify.execute(", "                select(SourceClassification).where(SourceClassification.article_id == article_id)", "            )", "        ).scalar_one()", "", "", "async def _run_demote_chain(*, incoming_id: UUID, response_ids: list[UUID]):", "    \"\"\"Drive classification + the write for a seeded same-publisher pair.\"\"\"", "    api_helper = APIHelper()", "    try:", "        async with sessionmanager_datalake.session() as session:", "            return await _classify_and_maybe_attach(", "                session,", "                api_helper,", "                incoming_article=_incoming_article(", "                    headline=_DEMOTE_HEADLINE,", "                    url=\"https://paper-b.example/story\",", "                    date_published=datetime(2026, 4, 6, tzinfo=timezone.utc),", "                ),", "                incoming_article_id=incoming_id,", "                incoming_response_id=response_ids[1],", "                incoming_chunks=_mid_band_incoming_chunks(),", "            )", "    finally:", "        await api_helper.session.close()", "", "", "@pytest.mark.asyncio", "async def test_verbatim_same_publisher_pair_keeps_its_join_and_persists_the_skip(", "    clean_article_tables, monkeypatch", "):", "    \"\"\"AC1 end to end: a verbatim republish stays grouped and says so on the row.", "", "    Enforcement is ON, both sides share a publisher, and the verdict calls the pair", "    a word-for-word reprint \u2014 the case the demote used to split. The join survives,", "    which also means ``match_info`` is persisted rather than discarded, so the skip", "    is readable in SQL rather than only from a log line.", "    \"\"\"", "    _pin_demote_config(monkeypatch, enforce=True)", "    _stub_verdict(monkeypatch, {\"event\": \"same\", \"verbatim\": True, \"reason\": \"identical body\"})", "", "    response_ids = await _seed_response_ids(2)", "    candidate_id, incoming_id = await _seed_same_publisher_pair(", "        # Same publisher as the incoming article.", "        candidate_url=\"https://paper-b.example/older-story\",", "        response_ids=response_ids,", "    )", "", "    plan = await _run_demote_chain(incoming_id=incoming_id, response_ids=response_ids)", "", "    assert plan.classification == DeduplicationClassification.SYNDICATION_CANDIDATE", "    assert plan.rejected_match_info is None", "", "    persisted = await _classification_row(incoming_id)", "    assert persisted.matched_article_id == candidate_id", "    assert persisted.match_info[\"same_publisher\"][\"verbatim_skipped\"] is True", "    assert persisted.match_info[\"same_publisher\"][\"eligible\"] is False", "", "    candidate_row = await _classification_row(candidate_id)", "    assert persisted.syndication_group_id == candidate_row.syndication_group_id", "", "", "@pytest.mark.asyncio", "async def test_applied_same_publisher_demote_persists_its_adjudication(", "    clean_article_tables, monkeypatch", "):", "    \"\"\"AC2 end to end: a non-verbatim pair is split, and the split is auditable.", "", "    The article gets its own singleton with no lineage, and the verifier's verdict", "    lands on that row \u2014 so an applied demote is distinguishable in SQL from an", "    article that never matched anything, which is what makes the post-flip split", "    rate measurable.", "    \"\"\"", "    _pin_demote_config(monkeypatch, enforce=True)", "    _stub_verdict(monkeypatch, {\"event\": \"same\", \"verbatim\": False, \"reason\": \"serial release\"})", "", "    response_ids = await _seed_response_ids(2)", "    candidate_id, incoming_id = await _seed_same_publisher_pair(", "        candidate_url=\"https://paper-b.example/older-story\",", "        response_ids=response_ids,", "    )", "", "    plan = await _run_demote_chain(incoming_id=incoming_id, response_ids=response_ids)", "", "    assert plan.classification == DeduplicationClassification.UNIQUE", "    assert plan.match_info == {}", "", "    persisted = await _classification_row(incoming_id)", "    assert persisted.matched_article_id is None", "    assert persisted.match_info is not None", "    assert persisted.match_info[\"llm_verdict\"][\"verbatim\"] is False", "    assert persisted.match_info[\"same_publisher\"][\"eligible\"] is True", "    assert persisted.match_info[\"same_publisher\"][\"verbatim_skipped\"] is False", "    # The row is UNIQUE, so it must not carry lineage or dedup chunk detail.", "    assert \"matched_article_id\" not in persisted.match_info", "    assert \"matched_chunk_index\" not in persisted.match_info", "", "    # The demote skipped group resolution entirely, so the candidate is not pulled", "    # into a group either \u2014 the pair is split, not merely re-parented.", "    async with sessionmanager_datalake.session() as verify:", "        candidate_row = (", "            await verify.execute(", "                select(SourceClassification).where(SourceClassification.article_id == candidate_id)", "            )", "        ).scalar_one_or_none()", "    assert candidate_row is None", "", "", "@pytest.mark.asyncio", "async def test_non_demote_unique_outcome_also_persists_its_adjudication(", "    clean_article_tables, monkeypatch", "):", "    \"\"\"The channel is not scoped to the same-publisher demote.", "", "    A cross-publisher pair the verifier calls a different event lands on UNIQUE by", "    the verdict alone, and its adjudication persists the same way. Without this,", "    every UNIQUE-by-verifier decision except the demote would still be answerable", "    only from logs.", "    \"\"\"", "    _pin_demote_config(monkeypatch, enforce=True)", "    _stub_verdict(monkeypatch, {\"event\": \"different\", \"verbatim\": None, \"reason\": \"distinct\"})", "", "    response_ids = await _seed_response_ids(2)", "    _candidate_id, incoming_id = await _seed_same_publisher_pair(", "        candidate_url=\"https://wire-a.example/story\",", "        response_ids=response_ids,", "    )", "", "    plan = await _run_demote_chain(incoming_id=incoming_id, response_ids=response_ids)", "", "    assert plan.classification == DeduplicationClassification.UNIQUE", "", "    persisted = await _classification_row(incoming_id)", "    assert persisted.matched_article_id is None", "    assert persisted.match_info is not None", "    assert persisted.match_info[\"llm_verdict\"][\"event\"] == \"different\"", "    assert persisted.match_info[\"same_publisher\"][\"is_same_publisher\"] is False", "", "", "@pytest.mark.asyncio", "async def test_unique_article_with_no_match_still_persists_null_match_info(", "    clean_article_tables, monkeypatch", "):", "    \"\"\"The noise guard: only a verifier rejection may populate the singleton row.", "", "    An article whose chunks match nothing never reaches the verifier, so its row", "    keeps ``match_info`` NULL exactly as it does today. If ordinary singletons", "    started carrying a payload, the reason the join-path contract excludes them", "    would be lost.", "    \"\"\"", "    _pin_demote_config(monkeypatch, enforce=True)", "", "    response_ids = await _seed_response_ids(2)", "    _candidate_id, incoming_id = await _seed_candidate_and_incoming(", "        candidate_headline=\"City council debates downtown parking overhaul plan\",", "        candidate_url=\"https://wire-a.example/story\",", "        incoming_headline=_DEMOTE_HEADLINE,", "        response_ids=response_ids,", "    )", "", "    api_helper = APIHelper()", "    try:", "        async with sessionmanager_datalake.session() as session:", "            plan = await _classify_and_maybe_attach(", "                session,", "                api_helper,", "                incoming_article=_incoming_article(", "                    headline=_DEMOTE_HEADLINE,", "                    url=\"https://paper-b.example/story\",", "                    date_published=datetime(2026, 4, 6, tzinfo=timezone.utc),", "                ),", "                incoming_article_id=incoming_id,", "                incoming_response_id=response_ids[1],", "                # Orthogonal to the candidate's chunks \u2014 nothing to match.", "                incoming_chunks=_chunk_vectors(0.0, 1.0),", "            )", "    finally:", "        await api_helper.session.close()", "", "    assert plan.classification == DeduplicationClassification.UNIQUE", "    assert plan.rejected_match_info is None", "", "    persisted = await _classification_row(incoming_id)", "    assert persisted.matched_article_id is None", "    assert persisted.match_info is None", "", "", "@pytest.mark.asyncio", "async def test_singleton_replay_does_not_overwrite_an_existing_row(clean_article_tables):", "    \"\"\"Replay idempotency must survive the new parameter.", "", "    ``_create_singleton_group_locked`` returns an existing row untouched when one is", "    already present \u2014 a concurrent writer or a replay under the same advisory lock.", "    A second attach carrying different adjudication must not rewrite the first.", "    \"\"\"", "    response_ids = await _seed_response_ids(1)", "    async with sessionmanager_datalake.session() as session:", "        article = Tables.Article()", "        session.add(article)", "        await session.flush()", "        session.add(", "            Tables.ZyteArticle(", "                article_id=article.id,", "                response_id=response_ids[0],", "                article_url=\"https://paper-b.example/seed\",", "                article_title=\"seed\",", "                content=\"seed\",", "                date_published=datetime(2026, 4, 4, tzinfo=timezone.utc),", "            )", "        )", "        await session.commit()", "", "        first_payload = {\"llm_band\": \"mid_band\", \"llm_verdict\": {\"event\": \"same\"}}", "        await attach_article_to_group(", "            session,", "            article_id=article.id,", "            matched_article_id=None,", "            similarity_score=None,", "            classification_method=CLASSIFICATION_METHOD_VECTOR,", "            rejected_match_info=first_payload,", "        )", "", "        await attach_article_to_group(", "            session,", "            article_id=article.id,", "            matched_article_id=None,", "            similarity_score=None,", "            classification_method=CLASSIFICATION_METHOD_VECTOR,", "            rejected_match_info={\"llm_band\": \"syndication_unique\", \"llm_failed\": True},", "        )", "", "    persisted = await _classification_row(article.id)", "    assert persisted.match_info == first_payload"], "blocks": [{"start": 1, "end": 52, "label": "Imports and module setup"}, {"start": 53, "end": 59, "label": "def _embedding"}, {"start": 60, "end": 72, "label": "def _chunk_vectors"}, {"start": 73, "end": 99, "label": "def _seed_response_ids"}, {"start": 100, "end": 136, "label": "def test_deduplicate_article_picks_nearest_match"}, {"start": 137, "end": 142, "label": "def _unit_vec"}, {"start": 143, "end": 150, "label": "def _perturb_to_similarity"}, {"start": 151, "end": 244, "label": "def test_dedup_recall_with_per_chunk_competitors"}, {"start": 245, "end": 307, "label": "def test_deduplicate_article_similarity_as_of_excludes_later_chunks"}, {"start": 308, "end": 361, "label": "def test_dedup_retry_query_uses_hnsw_index"}, {"start": 362, "end": 441, "label": "def test_dedup_retry_finds_match_in_other_article_when_excluded_dominates_topk"}, {"start": 442, "end": 524, "label": "def test_syndication_group_assignment_and_primary_reevaluation"}, {"start": 525, "end": 623, "label": "def test_syndication_group_join_reuses_existing_group"}, {"start": 624, "end": 678, "label": "def test_singleton_group_ids_are_non_deterministic"}, {"start": 679, "end": 769, "label": "def test_attach_skips_primary_recompute_when_new_member_cant_displace"}, {"start": 770, "end": 852, "label": "def test_attach_runs_primary_recompute_when_new_member_is_earlier"}, {"start": 853, "end": 923, "label": "def test_attach_skips_recompute_when_dated_primary_meets_undated_new_member"}, {"start": 924, "end": 1062, "label": "def test_crossed_concurrent_syndication_writes_do_not_deadlock"}, {"start": 1063, "end": 1134, "label": "def test_attach_article_to_group_with_frozen_group_id_attaches_to_existing"}, {"start": 1135, "end": 1167, "label": "def test_attach_article_to_group_with_frozen_group_id_raises_when_missing"}, {"start": 1168, "end": 1206, "label": "def test_attach_article_to_group_rejects_matched_without_frozen_group"}, {"start": 1207, "end": 1295, "label": "def test_attach_article_to_group_persists_match_info_on_join_path"}, {"start": 1296, "end": 1340, "label": "def test_attach_article_to_group_singleton_path_ignores_match_info"}, {"start": 1341, "end": 1467, "label": "def test_attach_article_to_group_merges_groups_on_matched_divergence"}, {"start": 1468, "end": 1596, "label": "def test_attach_article_to_group_merge_is_idempotent_across_concurrent_attempts"}, {"start": 1597, "end": 1611, "label": "def _incoming_article"}, {"start": 1612, "end": 1635, "label": "def _diluted_incoming_chunks"}, {"start": 1636, "end": 1656, "label": "def _pin_blocking_config"}, {"start": 1657, "end": 1708, "label": "def _classify_and_maybe_attach"}, {"start": 1709, "end": 1769, "label": "def _seed_candidate_and_incoming"}, {"start": 1770, "end": 1826, "label": "def test_title_blocking_key_unifies_verbatim_headline_cross_publisher"}, {"start": 1827, "end": 1865, "label": "def test_title_blocking_key_control_pair_different_headline_stays_unique"}, {"start": 1866, "end": 1918, "label": "def test_verifier_demotes_title_blocking_promotion_on_different_event"}, {"start": 1919, "end": 1970, "label": "def test_title_blocking_key_same_publisher_not_force_grouped"}, {"start": 1971, "end": 1985, "label": "def _pin_demote_config"}, {"start": 1986, "end": 1994, "label": "def _stub_verdict"}, {"start": 1995, "end": 1999, "label": "def _mid_band_incoming_chunks"}, {"start": 2000, "end": 2051, "label": "def _seed_same_publisher_pair"}, {"start": 2052, "end": 2060, "label": "def _classification_row"}, {"start": 2061, "end": 2081, "label": "def _run_demote_chain"}, {"start": 2082, "end": 2116, "label": "def test_verbatim_same_publisher_pair_keeps_its_join_and_persists_the_skip"}, {"start": 2117, "end": 2162, "label": "def test_applied_same_publisher_demote_persists_its_adjudication"}, {"start": 2163, "end": 2193, "label": "def test_non_demote_unique_outcome_also_persists_its_adjudication"}, {"start": 2194, "end": 2241, "label": "def test_unique_article_with_no_match_still_persists_null_match_info"}, {"start": 2242, "end": 2287, "label": "def test_singleton_replay_does_not_overwrite_an_existing_row"}], "lineCount": 2287, "sha256": "0bb71f128eefe0c42e9fd8d13b4c5e80577b928ef9a7fa8462090944be2544dd", "endsWithNewline": true});
